MERGE [purchase].[SupplierPaymentTerms] AS target USING (VALUES ('IMMEDIATE','Immediate',0,1),('NET15','Net 15 Days',15,0),('NET30','Net 30 Days',30,0),('NET45','Net 45 Days',45,0),('NET60','Net 60 Days',60,0)) AS source([Code],[Name],[Days],[Default]) ON target.[PaymentTermCode]=source.[Code] WHEN MATCHED THEN UPDATE SET [PaymentTermName]=source.[Name],[DueDays]=source.[Days],[IsDefault]=source.[Default],[IsActive]=1 WHEN NOT MATCHED THEN INSERT([PaymentTermCode],[PaymentTermName],[DueDays],[IsDefault],[IsActive],[CreatedBy]) VALUES(source.[Code],source.[Name],source.[Days],source.[Default],1,'database-seed');
